import{_ as p,a0 as s,w as e,s as d,ao as r,I as l,x as i,a1 as u,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"5 個最具生產力的 Linux 發行版 | LCTT x X-CMD","titleTemplate":false,"description":"5 個最具生產力的 Linux 發行版 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 個最具生產力的 Linux 發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 個最具生產力的 Linux 發行版 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190111 Top 5 Linux Distributions for Productivity","title":"5 個最具生產力的 Linux 發行版","tag":"201906","desc":""},"relativePath":"201906/20190111 Top 5 Linux Distributions for Productivity.md","filePath":"[post].md"}'),f={name:"201906/20190111 Top 5 Linux Distributions for Productivity.md"};function m(a,t,b,S,x,T){const n=s("Link");return e(),d("div",null,[t[43]||(t[43]=r('<h1 id="_5-個最具生產力的-linux-發行版" tabindex="-1">5 個最具生產力的 Linux 發行版 <a class="header-anchor" href="#_5-個最具生產力的-linux-發行版" aria-label="Permalink to “5 個最具生產力的 Linux 發行版”">​</a></h1><blockquote><p>如果你正在尋找一個適合開發工作的完美環境，我敢説你找不到比 Pop!_OS 更好的選擇。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_main.jpg?itok=2IKyg_7_" alt=""></p><p>必須承認的是，這樣的一個熱門話題其實很難被總結的話題。為什麼呢？首先，Linux 在就是一種有生產力的操作系統。由於它極強的可靠性和穩定的平台，使得完成工作變得很容易。其次為了衡量工作的效率，你需要考慮到哪項工作需要得到生產力方面的助推。是日常辦公？開發類工作？學校事務？數據挖掘？或者是人力資源？你可以看到這個問題有多複雜。</p><p>然而，這並不意味着某些發行版無法更好地配置將底層操作系統呈現為一個有效的平台來完成工作。恰恰相反，許多發行版在偏離生產力這條道路上越走越遠，所以你不會意識到你自己處在工作的窘境中，而是繼續挖掘自己的潛力在工期結束之前拼命趕上進度。這些 Linux 發行版可以幫助你化繁為簡，因此或許可以減少你工作流程中的痛點。</p><p>讓我們來看一下這些發行版併為你找出適合你的最佳選擇。為了更具條理，我按照生產力訴求把它們分成了幾類。這項任務本身也是一種挑戰，因為每個人在生產力提升上的需要是千差萬別的。然而，我所關注的是下列的幾項：</p><ul><li>常規：適於那些只需要有效地完成多項工作的人。</li><li>設計：適於那些從事設計創造和圖像處理的人。</li><li>開發：適於那些使用 Linux 桌面發行版來進行編程工作的人。</li><li>運維：適於那些需要一個發行版來促進其執行系統管理任務的人。</li><li>教育：適於那些需要桌面發行版可以助力他們在教育領域更高效的人。</li></ul><p>誠然，有很多很多類別的發行版可供挑選，其中的很多可能用起來十分得心應手，但這五種或許是你最為需要的。</p><h3 id="常規" tabindex="-1">常規 <a class="header-anchor" href="#常規" aria-label="Permalink to “常規”">​</a></h3>',9)),l("p",null,[t[1]||(t[1]=i("對於常規的生產力訴求來説，你不會找到比 ",-1)),u(n,{href:"https://www.ubuntu.com/"},{default:o(()=>[...t[0]||(t[0]=[i("Ubuntu",-1)])]),_:1}),t[2]||(t[2]=i(" 更為高效的了。在這個類別中首推 Ubuntu 最主要的原因是因為它實現了桌面操作系統、軟件、服務的無縫集成。你可能會問為什麼我不選擇同類別的 Linux Mint 呢？因為 Ubuntu 現在默認的的桌面環境為 GNOME 桌面，而它擁有 GNOME 許多擴展程序的優勢的加成（圖 1）。",-1))]),t[44]||(t[44]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_1.jpg?itok=yxez3X1w",alt:"GNOME Clipboard",title:"GNOME Clipboard"})],-1)),t[45]||(t[45]=l("p",null,[l("em",null,"圖 1：運行中的 GNOME 桌面的剪切板管理工具。")],-1)),t[46]||(t[46]=l("p",null,"這些擴展程序在提升生產力方面做了很多努力（所以 Ubuntu 比 Linux Mint 獲得了更多的認可）。但是 Ubuntu 不僅僅是裝了一個普通的 GNOME 桌面。事實上，他們致力於將它改進的更為輕量化、更為高效、以及用户友好度更高、開箱即用。總而言之，由於 Ubuntu 正確的融合了多種特性，開箱即用，完善的軟件支持（僅對工作方面而言），這些特性使它幾乎成為了生產力領域最為完美的一個平台。",-1)),t[47]||(t[47]=l("p",null,"不管你是要寫一篇文檔，製作一張電子表格，寫一個新的軟件，開發公司的網站，設計商用的圖形，管理一個服務器或是網絡，抑或是在你的公司內從事人力資源管理工作，Ubuntu 都可以滿足你的需求。Ubuntu 桌面發行版也並不要求你耗費很大的精力才能開始開始開展工作……它直接就能使用（並且工作的十分優秀）。最後，得益於它是基於 Debian 的，使得在 Ubuntu 上安裝第三方的軟件十分簡便。",-1)),t[48]||(t[48]=l("p",null,"很難不支持這一發行版獨佔生產力發行版列表的鰲頭，儘管 Ubuntu 幾乎已經成為幾乎所有“某某類頂級發行版”列表的榜首。",-1)),t[49]||(t[49]=l("h3",{id:"設計",tabindex:"-1"},[i("設計 "),l("a",{class:"header-anchor",href:"#設計","aria-label":"Permalink to “設計”"},"​")],-1)),l("p",null,[t[4]||(t[4]=i("如果你正在尋求提升你的平面設計效率，你不能錯過 ",-1)),u(n,{href:"https://labs.fedoraproject.org/en/design-suite/"},{default:o(()=>[...t[3]||(t[3]=[i("Fedora 設計套件",-1)])]),_:1}),t[5]||(t[5]=i("。這一 Fedora 衍生版是由負責 Fedora 相關的藝術作品的團隊親自操刀製作的。雖然其默認選擇的應用程序並不是一個龐大的工具集合，但它所包含的工具都是創建和處理圖像專用的。",-1))]),l("p",null,[t[7]||(t[7]=i("有了 GIMP、Inkscape、Darktable、Krita、Entangle、Blender、Pitivi、Scribus 等應用程序（圖 2），你可以找到完成圖像編輯工作所需要的一切。但是 Fedora 設計套件並不僅限於此。這個桌面平台還包括一堆教程，涵蓋了許多已安裝的應用程序。對於任何想要儘可能提高效率的人來説，這將是一些非常有用的信息。不過，我要説的是，GNOME 收藏夾中的教程並沒有超乎",-1)),u(n,{href:"https://fedoraproject.org/wiki/Design_Suite/Tutorials"},{default:o(()=>[...t[6]||(t[6]=[i("此頁中",-1)])]),_:1}),t[8]||(t[8]=i("鏈接的內容。",-1))]),t[50]||(t[50]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_2.jpg?itok=ke0b8qyH",alt:"Fedora Design Suite Favorites",title:"Fedora Design Suite Favorites"})],-1)),t[51]||(t[51]=l("p",null,[l("em",null,"圖 2：Fedora 設計套件收藏夾菜單包含了許多工具，可以讓你用於圖形設計。")],-1)),t[52]||(t[52]=l("p",null,"那些使用數碼相機的用户肯定會喜歡 Entangle 應用程序，它可以讓你在電腦上控制單反相機。",-1)),t[53]||(t[53]=l("h3",{id:"開發",tabindex:"-1"},[i("開發 "),l("a",{class:"header-anchor",href:"#開發","aria-label":"Permalink to “開發”"},"​")],-1)),l("p",null,[t[11]||(t[11]=i("幾乎所有的 Linux 發行版都是程序員的絕佳平台。然而，有一種特定的發行版脱穎而出，並超越了其他發行版，它將是你見過的用於編程類最有效率的工具之一。這個操作系統來自 ",-1)),u(n,{href:"https://system76.com/"},{default:o(()=>[...t[9]||(t[9]=[i("System76",-1)])]),_:1}),t[12]||(t[12]=i("（LCTT 譯註：一家美國的計算機制造商），名為 ",-1)),u(n,{href:"https://system76.com/pop"},{default:o(()=>[...t[10]||(t[10]=[i("Pop!_OS",-1)])]),_:1}),t[13]||(t[13]=i("。Pop!_OS 是專門為創作者定製的，但不是針對藝術類。相反，Pop!_OS 面向專門從事開發、編程和軟件製作的程序員。如果你需要一個既能完美的勝任開發工作又包含符合使用習慣的桌面操作系統的開發環境，Pop!_OS 將會是你的不二選擇。（圖 3）",-1))]),l("p",null,[t[15]||(t[15]=i("可能會讓你感到驚訝（考慮到這個操作系統是多麼“年輕”）的是 Pop!_OS 也是你將使用的基於 GNOME 平台的最穩定系統的之一。這意味着 Pop!_OS 不只是為創作者和創客準備的，也是為任何想要一個可靠的操作系統的人準備的。你可以下載針對你的硬件的專門 ISO 文件，這一點是許多用户十分欣賞的。如果你有英特爾硬件，",-1)),u(n,{href:"https://system76.com/pop"},{default:o(()=>[...t[14]||(t[14]=[i("下載",-1)])]),_:1}),t[16]||(t[16]=i(" Intel 或 AMD 的版本。如果你的顯卡是 NVIDIA，請下載該特定版本。不管怎樣，你肯定會得到針對不同平台進行特殊定製的穩定版本。",-1))]),t[54]||(t[54]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_3_0.jpg?itok=8UkCUfsD",alt:"Pop!_OS",title:"Pop!_OS"})],-1)),t[55]||(t[55]=l("p",null,[l("em",null,"圖 3：裝有 GNOME 桌面的 Pop!_OS 一覽。")],-1)),t[56]||(t[56]=l("p",null,"有趣的是，在 Pop!_OS 中，你不會找到太多預裝的開發工具。你也不會找到 IDE 或許多其他開發工具。但是，你可以在 Pop 商店中中找到所需的所有開發工具。",-1)),t[57]||(t[57]=l("h3",{id:"運維",tabindex:"-1"},[i("運維 "),l("a",{class:"header-anchor",href:"#運維","aria-label":"Permalink to “運維”"},"​")],-1)),l("p",null,[t[18]||(t[18]=i("如果你正在尋找適合系統管理的最具生產力的發行版，",-1)),u(n,{href:"https://www.debian.org/"},{default:o(()=>[...t[17]||(t[17]=[i("Debian",-1)])]),_:1}),t[19]||(t[19]=i(" 將會是你的不二之選。為什麼這麼説呢？因為 Debian 不僅僅擁有無與倫比的可靠性，它也是眾多能從苦海中將你解救出來的最好的一個發行版。Debian 是易用性和無限可能性的完美結合。最重要的是，因為它是許多其他發行版的基礎，所以可以打賭，如果你需要一個任務的管理工具，那麼它一定支持 Debian 系統。當然，我們討論的是一般的系統管理任務，這意味着大多數時候你需要使用終端窗口 SSH 連接到服務器（圖 4），或者在瀏覽器上使用網絡上基於 web 的 GUI 工具。既然如此為什麼還要使用一個增加複雜性的桌面呢（比如 Fedora 中的 SELinux 或 openSUSE 中的 YaST）呢？所以，應選擇更為簡潔易用的那一種。",-1))]),t[58]||(t[58]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_4.jpg?itok=c9yD3Xw2",alt:"Debian",title:"Debian"})],-1)),t[59]||(t[59]=l("p",null,[l("em",null,"圖 4：在 Debian 系統上通過 SSH 連接到遠程服務器。")],-1)),t[60]||(t[60]=l("p",null,"你可以選擇你想要的不同的桌面（包括 GNOME、Xfce、KDE、Cinnamon、MATE、LXDE），可以確保你所使用的桌面外觀最適合你的工作習慣。",-1)),t[61]||(t[61]=l("h3",{id:"教育",tabindex:"-1"},[i("教育 "),l("a",{class:"header-anchor",href:"#教育","aria-label":"Permalink to “教育”"},"​")],-1)),l("p",null,[t[21]||(t[21]=i("如果你是一名老師或學生，抑或是其他從事與教育相關工作的人士，你需要適當的工具來提高生產力。之前，有 Edubuntu 這樣的版本。這一版本位列教育類相關發行版排名的前列。然而，自從 Ubuntu 14.04 版之後這一發行版就再也沒有更新。還好，現在有一款基於 openSUSE 的新的以教育為基礎的發行版有望奪摘得桂冠。這一改版叫做 ",-1)),u(n,{href:"https://en.opensuse.org/openSUSE:Education-Li-f-e"},{default:o(()=>[...t[20]||(t[20]=[i("openSUSE:Education-Li-f-e",-1)])]),_:1}),t[22]||(t[22]=i("（Li-f-e：Linux For Education - 圖 5），它基於 openSUSE Leap 42.1 （所以它可能稍微有一點過時）。",-1))]),t[62]||(t[62]=r('<p>openSUSE:Education-Li-f-e 包含了以下工具：</p><ul><li>Brain Workshop（大腦工坊）：一種基於 dual n-back 模式的大腦訓練軟件（LCTT 譯註：dual n-back 訓練是一種科學的智力訓練方法，可以改善人的工作記憶和流體智力）</li><li>GCompris：一種針對青少年的教育軟件包</li><li>gElemental：一款元素週期表查看工具</li><li>iGNUit：一款通用的記憶卡片工具</li><li>Little Wizard：基於 Pascal 語言的少兒編程開發環境</li><li>Stellarium：天文模擬器</li><li>TuxMath：數學入門遊戲</li><li>TuxPaint：一款少兒繪畫軟件</li><li>TuxType：一款為少兒準備的打字入門軟件</li><li>wxMaxima：一個跨平台的計算機代數系統</li><li>Inkscape：矢量圖形編輯軟件</li><li>GIMP：圖像處理軟件（LCTT 譯註：被譽為 Linux 上的 PhotoShop）</li><li>Pencil：GUI 模型製作工具</li><li>Hugin：全景照片拼接及 HDR 效果混合軟件</li></ul><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_5.jpg?itok=oAFtV8nT" alt="Education" title="Education"></p><p><em>圖 5：openSUSE:Education-Li-f-e 發行版擁有大量的工具可以幫你在學校中變得更為高效。</em></p>',4)),l("p",null,[t[25]||(t[25]=i("同時還集成在 openSUSE:Education-Li-f-e 中的還有 ",-1)),u(n,{href:"https://en.opensuse.org/Portal:KIWI-LTSP"},{default:o(()=>[...t[23]||(t[23]=[i("KIWI-LTSP Server",-1)])]),_:1}),t[26]||(t[26]=i(" 。KIWI-LTSP 服務器是一個靈活的、經濟高效的解決方案，旨在使全世界的學校、企業和組織能夠輕鬆地安裝和部署桌面工作站。雖然這可能不會直接幫助學生變得更具生產力，但它肯定會使教育機構在部署供學生使用的桌面時更有效率。有關配置 KIWI-LTSP 的更多信息，請查看 openSUSE ",-1)),u(n,{href:"https://en.opensuse.org/SDB:KIWI-LTSP_quick_start"},{default:o(()=>[...t[24]||(t[24]=[i("KIWI-LTSP 快速入門指南",-1)])]),_:1}),t[27]||(t[27]=i("。",-1))]),t[63]||(t[63]=l("hr",null,null,-1)),l("p",null,[t[29]||(t[29]=i("via: ",-1)),u(n,{href:"https://www.linux.com/blog/learn/2019/1/top-5-linux-distributions-productivity"},{default:o(()=>[...t[28]||(t[28]=[i("https://www.linux.com/blog/learn/2019/1/top-5-linux-distributions-productivity",-1)])]),_:1})]),l("p",null,[t[34]||(t[34]=i("作者：",-1)),u(n,{href:"https://www.linux.com/users/jlwallen"},{default:o(()=>[...t[30]||(t[30]=[i("Jack Wallen",-1)])]),_:1}),t[35]||(t[35]=i(" 選題：",-1)),u(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[31]||(t[31]=[i("lujun9972",-1)])]),_:1}),t[36]||(t[36]=i(" 譯者：",-1)),u(n,{href:"https://github.com/qfzy1233"},{default:o(()=>[...t[32]||(t[32]=[i("qfzy1233",-1)])]),_:1}),t[37]||(t[37]=i(" 校對：",-1)),u(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[33]||(t[33]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[40]||(t[40]=i("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[38]||(t[38]=[i("LCTT",-1)])]),_:1}),t[41]||(t[41]=i(" 原創編譯，",-1)),u(n,{href:"https://linux.cn/"},{default:o(()=>[...t[39]||(t[39]=[i("Linux中國",-1)])]),_:1}),t[42]||(t[42]=i(" 榮譽推出",-1))])])}const E=p(f,[["render",m]]);export{P as __pageData,E as default};
